sys_variable_value.value:
(function execute(inputs, outputs) {
   var fieldMapping = {
       "v_meta":"meta",
       "v_realizado":"realizado",
       "v_ano":"ano",
       "v_indicador_de_endividamento_publico":"indicador_de_endividamento_publico"
   };


   var grMultiRow = new GlideRecord('sc_multi_row_question_answer');
   grMultiRow.addEncodedQuery('row_index=' + inputs.row_index + '^parent_id=' + inputs.parent_id);
   grMultiRow.query();

   while (grMultiRow.next()) {
       var questionName = grMultiRow.item_option_new.name;
       var value = grMultiRow.getValue('value');

       if (fieldMapping[questionName]) {
           fieldMapping[questionName] = value;
       }
   }

outputs.meta = fieldMapping['v_meta'];
outputs.realizado = fieldMapping['v_realizado'];
outputs.indicador_de_endividamento_publico = fieldMapping['v_indicador_de_endividamento_publico'];
outputs.ano = fieldMapping['v_ano'];

})(inputs, outputs);

